#include <iostream>
#include <fstream>
#include <vector>
#include <string>
#include <cstring>
#include <zlib.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <sys/stat.h>

namespace storage {

struct EncryptedBlob {
    unsigned char iv[16];
    unsigned char tag[16];
    std::vector<unsigned char> ciphertext;
};

class SecureStorage {
private:
    unsigned char master_key_[32];
    static constexpr size_t MAX_ENCRYPTED_SIZE = 50 * 1024 * 1024; // 50MB encrypted limit
    static constexpr size_t CHUNK_SIZE = 16384;

    bool decrypt_blob(const EncryptedBlob& blob, std::vector<unsigned char>& plaintext) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) return false;

        if (EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, master_key_, blob.iv) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return false;
        }

        plaintext.resize(blob.ciphertext.size());
        int len = 0;
        if (EVP_DecryptUpdate(ctx, plaintext.data(), &len, blob.ciphertext.data(), blob.ciphertext.size()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return false;
        }

        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, 16, (void*)blob.tag) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return false;
        }

        int final_len = 0;
        if (EVP_DecryptFinal_ex(ctx, plaintext.data() + len, &final_len) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return false;
        }
        plaintext.resize(len + final_len);
        EVP_CIPHER_CTX_free(ctx);
        return true;
    }

    // Validates compressed stream metadata before full decompression
    bool validate_compressed_header(const unsigned char* data, size_t len) {
        if (len < 10) return false;
        // Check zlib/gzip magic bytes
        if (data[0] == 0x1f && data[1] == 0x8b) return true; // gzip
        if ((data[0] & 0x0F) == 0x08) return true; // zlib deflate
        return false;
    }

    // Computes decompression ratio limit based on input characteristics
    size_t compute_max_output(size_t compressed_size) {
        // Allow up to 10:1 ratio for legitimate compressed data
        // This is conservative but handles most real-world documents
        size_t ratio_limit = compressed_size * 10ULL;
        size_t absolute_limit = 512ULL * 1024 * 1024; // 512MB absolute cap
        return (ratio_limit < absolute_limit) ? ratio_limit : absolute_limit;
    }

public:
    SecureStorage(const unsigned char* key) {
        memcpy(master_key_, key, 32);
    }

    // Process an uploaded encrypted+compressed document
    int process_document(const std::string& input_path, const std::string& output_dir) {
        // Step 1: Read encrypted blob from disk
        std::ifstream file(input_path, std::ios::binary);
        if (!file) return -1;

        file.seekg(0, std::ios::end);
        std::streamoff off = file.tellg();
        if (off < 0) return -1;
        size_t file_size = static_cast<size_t>(off);
        file.seekg(0, std::ios::beg);

        // Must contain at least IV (16) + tag (16) before any ciphertext.
        // Prevents integer underflow on (file_size - 32).
        if (file_size < 32) {
            return -1; // Malformed / too small
        }

        if (file_size > MAX_ENCRYPTED_SIZE) {
            return -2; // Encrypted payload too large
        }

        EncryptedBlob blob;
        if (!file.read(reinterpret_cast<char*>(blob.iv), 16)) return -1;
        if (!file.read(reinterpret_cast<char*>(blob.tag), 16)) return -1;
        size_t ct_size = file_size - 32;
        blob.ciphertext.resize(ct_size);
        if (ct_size > 0 && !file.read(reinterpret_cast<char*>(blob.ciphertext.data()), ct_size)) {
            return -1;
        }
        file.close();

        // Step 2: Decrypt
        std::vector<unsigned char> compressed_data;
        if (!decrypt_blob(blob, compressed_data)) {
            return -3; // Decryption/authentication failed
        }

        // Step 3: Validate compressed format
        if (!validate_compressed_header(compressed_data.data(), compressed_data.size())) {
            return -4;
        }

        // Step 4: Decompress with ratio limiting
        size_t max_output = compute_max_output(compressed_data.size());

        z_stream strm;
        memset(&strm, 0, sizeof(strm));
        if (inflateInit2(&strm, 15 + 32) != Z_OK) return -5;

        strm.next_in = compressed_data.data();
        strm.avail_in = compressed_data.size();

        std::vector<unsigned char> output;
        output.reserve(std::min(max_output, (size_t)(compressed_data.size() * 4)));

        unsigned char out_buf[CHUNK_SIZE];
        size_t total_output = 0;
        int ret;

        do {
            strm.next_out = out_buf;
            strm.avail_out = CHUNK_SIZE;
            ret = inflate(&strm, Z_NO_FLUSH);

            if (ret == Z_STREAM_ERROR || ret == Z_DATA_ERROR || ret == Z_MEM_ERROR) {
                inflateEnd(&strm);
                return -6;
            }

            size_t have = CHUNK_SIZE - strm.avail_out;
            total_output += have;

            if (total_output > max_output) {
                inflateEnd(&strm);
                return -7; // Decompression bomb detected
            }

            output.insert(output.end(), out_buf, out_buf + have);
        } while (ret != Z_STREAM_END);

        inflateEnd(&strm);

        // Step 5: Write decompressed output
        std::string out_path = output_dir + "/document.bin";
        std::ofstream out_file(out_path, std::ios::binary);
        if (!out_file) return -8;
        out_file.write(reinterpret_cast<char*>(output.data()), output.size());
        out_file.close();

        return 0;
    }
};

} // namespace storage

int main(int argc, char* argv[]) {
    if (argc != 4) {
        std::cerr << "Usage: " << argv[0] << " <keyfile> <input> <output_dir>" << std::endl;
        return 1;
    }

    unsigned char key[32];
    std::ifstream kf(argv[1], std::ios::binary);
    if (!kf || !kf.read(reinterpret_cast<char*>(key), 32)) {
        std::cerr << "Failed to read key" << std::endl;
        return 1;
    }

    storage::SecureStorage store(key);
    int result = store.process_document(argv[2], argv[3]);
    if (result != 0) {
        std::cerr << "Processing failed with code: " << result << std::endl;
        return 1;
    }

    std::cout << "Document processed successfully" << std::endl;
    return 0;
}
